import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 5 No wrong numbers","description":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 5 No wrong numbers","description":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 4 An exciting trip","link":"/life/english/new-concept/book-2/unit-01/lesson-004"},"next":{"text":"第二册：实践与进步 · Lesson 6 Percy Buttons","link":"/life/english/new-concept/book-2/unit-01/lesson-006"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 4 An exciting trip","link":"/life/english/new-concept/book-2/unit-01/lesson-004"},"next":{"text":"第二册：实践与进步 · Lesson 6 Percy Buttons","link":"/life/english/new-concept/book-2/unit-01/lesson-006"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-005.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-005.md"}'),s={name:"life/english/new-concept/book-2/unit-01/lesson-005.md"};function o(r,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-5-no-wrong-numbers" tabindex="-1">第二册：实践与进步 · Lesson 5 No wrong numbers <a class="header-anchor" href="#第二册-实践与进步-·-lesson-5-no-wrong-numbers" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 5 No wrong numbers&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>两间相距不远的工作室通过简单信号保持联系；练习表达持续联系和信息传递的结果。本课的语言观察是：have received 强调已经收到的信息数量，而 receive every day 描述固定习惯。完成时中的 received 是过去分词，不是因为前面有过去时间。完成学习后，请描述两个团队如何传递消息，区分已经收到和准备回复的内容。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>signal</td><td>/ˈsɪɡnəl/</td><td>n.</td><td>信号</td><td>a clear signal</td></tr><tr><td>distance</td><td>/ˈdɪstəns/</td><td>n.</td><td>距离</td><td>a short distance</td></tr><tr><td>receive</td><td>/rɪˈsiːv/</td><td>v.</td><td>收到</td><td>receive a letter</td></tr><tr><td>contact</td><td>/ˈkɒntækt/</td><td>n.</td><td>联系</td><td>keep in contact</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>keep in contact — 保持联系</li><li>send a signal — 发出信号，signal 是可数名词</li></ul><h2 id="语法讲解-现在完成时与过去时间" tabindex="-1">语法讲解：现在完成时与过去时间 <a class="header-anchor" href="#语法讲解-现在完成时与过去时间" aria-label="Permalink to &quot;语法讲解：现在完成时与过去时间&quot;">​</a></h2><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：have received 强调已经收到的信息数量，而 receive every day 描述固定习惯。完成时中的 received 是过去分词，不是因为前面有过去时间。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Our studio has received six messages today.</p></blockquote><p>我们的工作室今天已收到六条消息。</p><p>Our studio 是整体单数主语，所以用 has；six messages 表示累计结果，today 的时间范围延伸到现在。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>receive 不等于 send；已收到用 have received，不要写 have receive。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 six messages today 分为一个信息语块，注意 messages 的词尾 /ɪz/。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Our studio has received six messages today. The last message arrived at noon. We will answer it after lunch.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>描述两个团队如何传递消息，区分已经收到和准备回复的内容。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：Our studio 是整体单数主语，所以用 has；six messages 表示累计结果，today 的时间范围延伸到现在。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：receive 不等于 send；已收到用 have received，不要写 have receive。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 receive 的形式：The studio has ___ six messages.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> received</p><p><strong>解析：</strong> has 后要求过去分词 received。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>最后一条消息几点到达？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> At noon.</p><p><strong>解析：</strong> 第二句的 at noon 修饰 arrived，不是 answer。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 The last message arrived at noon 改为否定句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The last message did not arrive at noon.</p><p><strong>解析：</strong> did not 后用 arrive 原形。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：现在完成时与过去时间。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-004">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-006">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=a(s,[["render",o]]);export{p as __pageData,g as default};
